  [("Juntarse todos en un solo punto.", "Quedan lugares vacíos y los rivales cierran fácil.", "Repartan el espacio: centro, lados y atrás."), ("Quedarse lejos de quien lleva la pelota.", "No puedes ofrecer un pase.", "Acompaña a un pase corto.")],
